BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
DO $guard$ BEGIN
 IF (SELECT count(*) FROM public.landing_pages p JOIN public.tenants t ON t.id=p.tenant_id WHERE t.slug IN ('3dyanimda','3dsanayi','maketyanimda','parcayanimda') AND p.kind='location' AND p.status='draft')<>656 THEN RAISE EXCEPTION 'Expected 656 draft location records; review changed inventory'; END IF;
 IF (SELECT count(*) FROM public.landing_pages p JOIN public.tenants t ON t.id=p.tenant_id JOIN jsonb_to_recordset('[{"brand":"3dyanimda","path":"/3d-baski","q":"Prototipimi nasıl teslim alabilirim?","a":"Baskı numuneleri kargo, kurye veya elden teslim edilebilir; İstanbul dışındaki adreslere de kargo gönderimi yapılır. Örnek Mahallesi, Ataşehir’deki atölyeden teslim alacaksanız gelmeden randevu oluşturun. Numunenin adedi, ambalaj ihtiyacı ve hedef adresi teklif talebinize ekleyin."},{"brand":"3dyanimda","path":"/3d-tarama","q":"Prototipi taşımadan yerinde 3D tarama yaptırabilir miyim?","a":"Yerinde 3D tarama hizmeti veriyoruz. İncelenecek prototipin fotoğraflarını, yaklaşık boyutunu ve bulunduğu adresi paylaşın; erişim ve çekim koşullarını birlikte planlayalım. Atölyeye getirmeyi tercih ederseniz Örnek Mahallesi’ndeki çalışma noktası için önceden randevu alın."},{"brand":"3dyanimda","path":"/3d-modelleme","q":"Tasarım için fiziksel örneği nasıl ulaştırabilirim?","a":"Referans ürününüzü kargo veya kurye ile gönderebilir, randevu alarak elden getirebilirsiniz. Şehir dışındaki ekiplerle de kargo üzerinden numune alışverişi yapılabilir. Gönderiye ürün kodunu ve modelde değiştirilmesini istediğiniz özellikleri eklemek, örneği doğru çizim revizyonuyla eşleştirmeye yardımcı olur."},{"brand":"3dyanimda","path":"/bolgeler/istanbul","q":"Atölye ziyareti ve İstanbul dışı gönderim nasıl düzenleniyor?","a":"Örnek Mahallesi, Ataşehir’deki atölyeye ziyaret öncesinde randevu alınmalıdır. Ürün tesliminde elden teslim, kurye ve kargo seçenekleri bulunur; diğer şehirlere de kargo gönderilir. Ürün yerinden taşınamıyorsa yerinde 3D tarama talebinizi adres ve ürün fotoğraflarıyla iletebilirsiniz."},{"brand":"3dsanayi","path":"/3d-baski","q":"Aparat numunesinin sevkiyatı nasıl yapılır?","a":"Aparat ve fikstür numunelerinde kurye, kargo ya da elden teslim seçeneklerini kullanabilirsiniz. Başka şehirdeki tesislere kargo gönderimi de yapılır. Teslim noktasını ve kabul edecek kişiyi talepte belirtin; elden teslim için Örnek Mahallesi’ndeki atölyeye gelmeden randevulaşın."},{"brand":"3dsanayi","path":"/3d-tarama","q":"İş parçası tesisimizde taranabilir mi?","a":"Yerinde 3D tarama hizmetimiz bulunuyor. Tesis adresiyle birlikte parçanın ölçülerini, erişilebilen yüzeylerini ve çalışma alanının fotoğraflarını iletin. Saha çalışmasının kapsamı talebe göre belirlenir. Tarama ziyareti, makine kurulumu veya üretim hattında kabul testiyle aynı hizmet olarak değerlendirilmez."},{"brand":"3dsanayi","path":"/3d-modelleme","q":"Referans iş parçasını modelleme için gönderebilir miyiz?","a":"İş parçası kargo ya da kurye ile ulaştırılabilir; şehirler arası numune gönderimi de mümkündür. Parça kodu, çizim revizyonu ve korunacak referans yüzeylerini paket notunda belirtin. Numuneyi elden teslim etmek isteyen üretim ekipleri Ataşehir Örnek Mahallesi atölyesi için önceden randevu almalıdır."},{"brand":"3dsanayi","path":"/bolgeler/istanbul","q":"Saha taramasıyla numune teslimini birlikte planlayabilir miyiz?","a":"Talebinizde iki ihtiyacı ayrı belirterek planlayabilirsiniz: yerinde tarama hizmeti mevcuttur; üretilen numuneler kargo, kurye veya elden teslim edilebilir. İstanbul dışındaki tesislere kargo seçeneği de vardır. Atölyede görüşme ve elden teslim için önceden randevu gereklidir."},{"brand":"maketyanimda","path":"/3d-baski","q":"Maket parçalarını başka şehre gönderebilir misiniz?","a":"Diğer şehirlere kargo gönderimi yapılır; kurye ve elden teslim seçenekleri de bulunur. Maketin dış ölçüsü, narin detayları ve modüler parçaları taşıma hazırlığında değerlendirilmelidir. Örnek Mahallesi’ndeki atölyeden teslim almak için önceden randevu alın; kurulum ihtiyacını ayrıca belirtin."},{"brand":"maketyanimda","path":"/3d-tarama","q":"Maket referansı bulunduğu yerde taranabilir mi?","a":"Yerinde 3D tarama sunuyoruz. Referans nesnenin fotoğrafı, yaklaşık boyutu ve bulunduğu mekâna erişim bilgisiyle talep oluşturabilirsiniz. Taranacak nesnenin tüm bir bina mı, bir cephe detayı mı yoksa küçük bir obje mi olduğunu açıkça belirtin; uygulanabilir kapsam ön değerlendirmede belirlenir."},{"brand":"maketyanimda","path":"/3d-modelleme","q":"Fiziksel maket veya obje üzerinden çalışmak için atölyeye gelebilir miyim?","a":"Ataşehir Örnek Mahallesi’ndeki atölyeyi randevu alarak ziyaret edebilirsiniz. Referans objeyi kargo ya da kurye ile ulaştırmak da mümkündür. Şehir dışından gelecek örneklerde pakete ölçek bilgisini, parça listesini ve dijital çizimlerin dosya adlarını ekleyin."},{"brand":"maketyanimda","path":"/bolgeler/istanbul","q":"Maket tesliminde hangi ulaşım seçenekleri bulunuyor?","a":"Elden teslim, kurye ve kargo seçenekleri sunulur; İstanbul dışına da kargo gönderilebilir. Taşıma biçimi değerlendirilirken kaide ölçüsü ve ayrılabilir model parçaları paylaşılmalıdır. Randevulu atölye tesliminin yanında, fiziksel referanslar için yerinde 3D tarama da talep edilebilir."},{"brand":"parcayanimda","path":"/3d-baski","q":"Üretilen özel parçayı nasıl teslim alırım?","a":"Parçanız kargo veya kurye ile gönderilebilir; diğer şehirler için de kargo seçeneği vardır. Elden teslim tercihinde Örnek Mahallesi, Ataşehir atölyesine gelmeden randevu almalısınız. Birden fazla parçanın sipariş edildiği işlerde parça kodlarını ve adetleri teslim listesiyle karşılaştırın."},{"brand":"parcayanimda","path":"/3d-tarama","q":"Sökülemeyen parçalar için yerinde tarama yapıyor musunuz?","a":"Yerinde 3D tarama hizmeti veriyoruz. Parçanın montaj üzerindeki durumunu, görünmeyen yüzeylerini ve bulunduğu adresi gösteren bilgilerle başvurun. Sökülmeyen bir parçanın kapalı yüzeylerinin de mutlaka ölçülebileceği varsayılmamalıdır; erişim ve istenen çıktı çalışma öncesinde değerlendirilir."},{"brand":"parcayanimda","path":"/3d-modelleme","q":"Kırık numuneyi şehir dışından gönderebilir miyim?","a":"Evet, kargo ile numune ulaştırabilirsiniz. Kopan küçük parçaları ayrı koruyarak aynı numune koduyla paketleyin; montaj yerinin fotoğraflarını dijital olarak paylaşın. Kurye ve randevulu elden teslim de mümkündür. Örneğin size geri gönderilmesini istiyorsanız bunu talep notuna ekleyin."},{"brand":"parcayanimda","path":"/bolgeler/istanbul","q":"Numuneyi getirmek zorunda mıyım; atölye randevusu gerekiyor mu?","a":"Numune için kargo ve kurye kullanabilir veya önceden randevu alarak Örnek Mahallesi’ndeki atölyeye gelebilirsiniz. Şehirler arası kargo seçeneği de bulunur. Parça bulunduğu yerde incelenecekse yerinde 3D tarama talebi oluşturun; erişim koşulları fotoğraflarla değerlendirilir."}]'::jsonb) AS x(brand text,path text,q text,a text) ON x.brand=t.slug AND x.path=p.path WHERE p.status='draft')<>16 THEN RAISE EXCEPTION 'Expected 16 draft core routes'; END IF;
END $guard$;
UPDATE public.landing_pages p SET evidence=concat_ws(E'\n',nullif(p.evidence,''),'İşletme teyidi — 7 Ekim 2026: Kargo, kurye ve elden teslim mevcuttur; diğer şehirlere kargo gönderilir. 3D tarama ve yerinde tarama hizmeti vardır. Örnek Mahallesi, Ataşehir atölyesine gelmeden randevu alınmalıdır. Bu kayıt hizmet koşullarının teyididir; özgünlük/yayın onayı değildir.'),reviewed_at='2026-10-07T20:48:02+03:00'::timestamptz,updated_at=now() FROM public.tenants t WHERE p.tenant_id=t.id AND t.slug IN ('3dyanimda','3dsanayi','maketyanimda','parcayanimda') AND p.kind='location' AND p.status='draft' AND position('İşletme teyidi — 7 Ekim 2026:' in p.evidence)=0;
WITH patch AS (SELECT * FROM jsonb_to_recordset('[{"brand":"3dyanimda","path":"/3d-baski","q":"Prototipimi nasıl teslim alabilirim?","a":"Baskı numuneleri kargo, kurye veya elden teslim edilebilir; İstanbul dışındaki adreslere de kargo gönderimi yapılır. Örnek Mahallesi, Ataşehir’deki atölyeden teslim alacaksanız gelmeden randevu oluşturun. Numunenin adedi, ambalaj ihtiyacı ve hedef adresi teklif talebinize ekleyin."},{"brand":"3dyanimda","path":"/3d-tarama","q":"Prototipi taşımadan yerinde 3D tarama yaptırabilir miyim?","a":"Yerinde 3D tarama hizmeti veriyoruz. İncelenecek prototipin fotoğraflarını, yaklaşık boyutunu ve bulunduğu adresi paylaşın; erişim ve çekim koşullarını birlikte planlayalım. Atölyeye getirmeyi tercih ederseniz Örnek Mahallesi’ndeki çalışma noktası için önceden randevu alın."},{"brand":"3dyanimda","path":"/3d-modelleme","q":"Tasarım için fiziksel örneği nasıl ulaştırabilirim?","a":"Referans ürününüzü kargo veya kurye ile gönderebilir, randevu alarak elden getirebilirsiniz. Şehir dışındaki ekiplerle de kargo üzerinden numune alışverişi yapılabilir. Gönderiye ürün kodunu ve modelde değiştirilmesini istediğiniz özellikleri eklemek, örneği doğru çizim revizyonuyla eşleştirmeye yardımcı olur."},{"brand":"3dyanimda","path":"/bolgeler/istanbul","q":"Atölye ziyareti ve İstanbul dışı gönderim nasıl düzenleniyor?","a":"Örnek Mahallesi, Ataşehir’deki atölyeye ziyaret öncesinde randevu alınmalıdır. Ürün tesliminde elden teslim, kurye ve kargo seçenekleri bulunur; diğer şehirlere de kargo gönderilir. Ürün yerinden taşınamıyorsa yerinde 3D tarama talebinizi adres ve ürün fotoğraflarıyla iletebilirsiniz."},{"brand":"3dsanayi","path":"/3d-baski","q":"Aparat numunesinin sevkiyatı nasıl yapılır?","a":"Aparat ve fikstür numunelerinde kurye, kargo ya da elden teslim seçeneklerini kullanabilirsiniz. Başka şehirdeki tesislere kargo gönderimi de yapılır. Teslim noktasını ve kabul edecek kişiyi talepte belirtin; elden teslim için Örnek Mahallesi’ndeki atölyeye gelmeden randevulaşın."},{"brand":"3dsanayi","path":"/3d-tarama","q":"İş parçası tesisimizde taranabilir mi?","a":"Yerinde 3D tarama hizmetimiz bulunuyor. Tesis adresiyle birlikte parçanın ölçülerini, erişilebilen yüzeylerini ve çalışma alanının fotoğraflarını iletin. Saha çalışmasının kapsamı talebe göre belirlenir. Tarama ziyareti, makine kurulumu veya üretim hattında kabul testiyle aynı hizmet olarak değerlendirilmez."},{"brand":"3dsanayi","path":"/3d-modelleme","q":"Referans iş parçasını modelleme için gönderebilir miyiz?","a":"İş parçası kargo ya da kurye ile ulaştırılabilir; şehirler arası numune gönderimi de mümkündür. Parça kodu, çizim revizyonu ve korunacak referans yüzeylerini paket notunda belirtin. Numuneyi elden teslim etmek isteyen üretim ekipleri Ataşehir Örnek Mahallesi atölyesi için önceden randevu almalıdır."},{"brand":"3dsanayi","path":"/bolgeler/istanbul","q":"Saha taramasıyla numune teslimini birlikte planlayabilir miyiz?","a":"Talebinizde iki ihtiyacı ayrı belirterek planlayabilirsiniz: yerinde tarama hizmeti mevcuttur; üretilen numuneler kargo, kurye veya elden teslim edilebilir. İstanbul dışındaki tesislere kargo seçeneği de vardır. Atölyede görüşme ve elden teslim için önceden randevu gereklidir."},{"brand":"maketyanimda","path":"/3d-baski","q":"Maket parçalarını başka şehre gönderebilir misiniz?","a":"Diğer şehirlere kargo gönderimi yapılır; kurye ve elden teslim seçenekleri de bulunur. Maketin dış ölçüsü, narin detayları ve modüler parçaları taşıma hazırlığında değerlendirilmelidir. Örnek Mahallesi’ndeki atölyeden teslim almak için önceden randevu alın; kurulum ihtiyacını ayrıca belirtin."},{"brand":"maketyanimda","path":"/3d-tarama","q":"Maket referansı bulunduğu yerde taranabilir mi?","a":"Yerinde 3D tarama sunuyoruz. Referans nesnenin fotoğrafı, yaklaşık boyutu ve bulunduğu mekâna erişim bilgisiyle talep oluşturabilirsiniz. Taranacak nesnenin tüm bir bina mı, bir cephe detayı mı yoksa küçük bir obje mi olduğunu açıkça belirtin; uygulanabilir kapsam ön değerlendirmede belirlenir."},{"brand":"maketyanimda","path":"/3d-modelleme","q":"Fiziksel maket veya obje üzerinden çalışmak için atölyeye gelebilir miyim?","a":"Ataşehir Örnek Mahallesi’ndeki atölyeyi randevu alarak ziyaret edebilirsiniz. Referans objeyi kargo ya da kurye ile ulaştırmak da mümkündür. Şehir dışından gelecek örneklerde pakete ölçek bilgisini, parça listesini ve dijital çizimlerin dosya adlarını ekleyin."},{"brand":"maketyanimda","path":"/bolgeler/istanbul","q":"Maket tesliminde hangi ulaşım seçenekleri bulunuyor?","a":"Elden teslim, kurye ve kargo seçenekleri sunulur; İstanbul dışına da kargo gönderilebilir. Taşıma biçimi değerlendirilirken kaide ölçüsü ve ayrılabilir model parçaları paylaşılmalıdır. Randevulu atölye tesliminin yanında, fiziksel referanslar için yerinde 3D tarama da talep edilebilir."},{"brand":"parcayanimda","path":"/3d-baski","q":"Üretilen özel parçayı nasıl teslim alırım?","a":"Parçanız kargo veya kurye ile gönderilebilir; diğer şehirler için de kargo seçeneği vardır. Elden teslim tercihinde Örnek Mahallesi, Ataşehir atölyesine gelmeden randevu almalısınız. Birden fazla parçanın sipariş edildiği işlerde parça kodlarını ve adetleri teslim listesiyle karşılaştırın."},{"brand":"parcayanimda","path":"/3d-tarama","q":"Sökülemeyen parçalar için yerinde tarama yapıyor musunuz?","a":"Yerinde 3D tarama hizmeti veriyoruz. Parçanın montaj üzerindeki durumunu, görünmeyen yüzeylerini ve bulunduğu adresi gösteren bilgilerle başvurun. Sökülmeyen bir parçanın kapalı yüzeylerinin de mutlaka ölçülebileceği varsayılmamalıdır; erişim ve istenen çıktı çalışma öncesinde değerlendirilir."},{"brand":"parcayanimda","path":"/3d-modelleme","q":"Kırık numuneyi şehir dışından gönderebilir miyim?","a":"Evet, kargo ile numune ulaştırabilirsiniz. Kopan küçük parçaları ayrı koruyarak aynı numune koduyla paketleyin; montaj yerinin fotoğraflarını dijital olarak paylaşın. Kurye ve randevulu elden teslim de mümkündür. Örneğin size geri gönderilmesini istiyorsanız bunu talep notuna ekleyin."},{"brand":"parcayanimda","path":"/bolgeler/istanbul","q":"Numuneyi getirmek zorunda mıyım; atölye randevusu gerekiyor mu?","a":"Numune için kargo ve kurye kullanabilir veya önceden randevu alarak Örnek Mahallesi’ndeki atölyeye gelebilirsiniz. Şehirler arası kargo seçeneği de bulunur. Parça bulunduğu yerde incelenecekse yerinde 3D tarama talebi oluşturun; erişim koşulları fotoğraflarla değerlendirilir."}]'::jsonb) AS x(brand text,path text,q text,a text))
UPDATE public.landing_pages p SET faq=(SELECT coalesce(jsonb_agg(f),'[]'::jsonb) FROM jsonb_array_elements(p.faq) f WHERE f->>'q'<>x.q)||jsonb_build_array(jsonb_build_object('q',x.q,'a',x.a)),updated_at=now() FROM patch x,public.tenants t WHERE p.tenant_id=t.id AND t.slug=x.brand AND p.path=x.path AND p.status='draft';
COMMIT;
